U='u3'
def H(s,k,en,ur,ps,**m): add(s,k,en,ur,ps,kind='heading',**m)
def CAP(s,k,en,ur,ps): add(s,k,en,ur,ps,kind='caption')
NOTE=' Photographs are not reproduced; their captions are given. Watermark, border lines, page-edge shadows and handwriting are excluded.'
def fin(s,note):
    s['sourceNote']=note+NOTE; s['vocabulary']={}; save(s)
def regfig(n,i,name,hi,lo,ur_name,ps_name):
    b=('<text x="30" y="16" font-size="13" font-family="Arial,sans-serif" fill="#111">Bits 15</text>'
       '<line x1="82" y1="14" x2="330" y2="14" stroke="#111" stroke-dasharray="2 3"/><text x="334" y="16" font-size="13" font-family="Arial,sans-serif" fill="#111">0</text>'
       '<rect x="30" y="26" width="320" height="38" fill="#fff" stroke="#111" stroke-width="1.5"/>'+T(190,50,f'16-bit {name} register',14,'middle',400)
       +'<rect x="30" y="64" width="160" height="38" fill="#fff" stroke="#111" stroke-width="1.5"/>'+T(110,88,f'8-bit {hi} register',13,'middle',400)
       +'<rect x="190" y="64" width="160" height="38" fill="#fff" stroke="#111" stroke-width="1.5"/>'+T(270,88,f'8-bit {lo} register',13,'middle',400))
    return dict(id=f'cs11-s{n:03}-fig{i}',svg=svg(380,114,f'{name} register made of {hi} and {lo}',b),caption=f'{name} register: 16 bits made of two 8-bit registers {hi} and {lo}',captionUrdu=f'{ur_name} رجسٹر: ۱۶ بٹس، دو ۸ بٹ رجسٹرز {hi} اور {lo} سے بنا',captionPashto=f'{ps_name} رجستر: ۱۶ بټه، له دوو ۸ بټه رجسترونو {hi} او {lo} نه جوړ',labels=[lab(f'16-bit {name} register',f'۱۶ بٹ {ur_name} رجسٹر',f'۱۶ بټه {ps_name} رجستر'),lab(f'8-bit {hi} register',f'۸ بٹ {hi} رجسٹر',f'۸ بټه {hi} رجستر'),lab(f'8-bit {lo} register',f'۸ بٹ {lo} رجسٹر',f'۸ بټه {lo} رجستر')])
